// Natural Earth 1:50m countries (public domain) in a Lambert azimuthal equal-area projection centred on 17°E 1°N.
// Somaliland is drawn as part of Somalia; Western Sahara (eh) is a shape of its own.

// Regions of the UN geoscheme (M49)
export type AfricaMapRegion = 'northern' | 'western' | 'central' | 'eastern' | 'southern';

export type AfricaMapFrame = { x: number; y: number; width: number; height: number };

export type AfricaMapShape = {
	// Lowercase ISO 3166-1 alpha-2 code
	code: string;
	region: AfricaMapRegion;
	// SVG path data
	d: string;
	// Visual centre of the largest landmass
	x: number;
	y: number;
	// Radius of the largest circle that fits into that landmass
	r: number;
};

// Fits the mainland and Madagascar: Cabo Verde, Mauritius and the Seychelles lie outside of it
